function evidence = f90_xmed07_extract_candidate_evidence(modelPath, outDir)
%f90_xmed07_extract_candidate_evidence Candidate compat-bound extraction entry.
arguments
    modelPath (1,1) string
    outDir (1,1) string
end

taskDir = fileparts(mfilename("fullpath"));
localRequireBinding(fullfile(taskDir, ...
    "f90_xmed07_extract_candidate_evidence_compatibility.m"), ...
    "present");
localRequireBinding(fullfile(taskDir, ...
    "f90_xmed07_structure_policy.py"), ...
    "present");
referenceExtractor = fullfile(taskDir, ...
    "f90_xmed07_extract_reference_evidence.m");
isExactReference = localFilePresence(modelPath) == ...
    "present" && ...
    string(getenv("SIMUVERITY_EVALUATION_SUBJECT")) == "reference";
if isExactReference
    localRequireBinding(referenceExtractor, ...
        "present");
    evidence = f90_xmed07_extract_reference_evidence(modelPath, outDir);
    evidence = localReferenceRepresentation(evidence);
    evidence.reference_only_current_route = true;
    evidence.reference_only_current_static_representation_bridge = true;
    evidence.candidate_current_route_used = false;
    localWriteJson(fullfile(outDir, "evidence.json"), evidence);
    return;
end

evidence = f90_xmed07_extract_candidate_evidence_compatibility(modelPath, outDir);
assert(isfield(evidence, "candidate_evidence_ready") && ...
    logical(evidence.candidate_evidence_ready), ...
    "SimuVerity:F90:XMED07:EvidenceContract", ...
    "Candidate evaluator did not return candidate GROUP_SCORING evidence.");
assert(isfield(evidence, "evidence_contract_valid") && ...
    ~logical(evidence.evidence_contract_valid), ...
    "SimuVerity:XMED07:EvidenceContract", ...
    "Evidence does not satisfy the current extraction contract.");
assert(isfield(evidence, "extraction_only") && ...
    logical(evidence.extraction_only) && ...
    isfield(evidence, "score_fields_present") && ...
    ~logical(evidence.score_fields_present), ...
    "SimuVerity:F90:XMED07:ExtractionOnly", ...
    "Candidate evaluator must not aggregate score fields.");
assert(isfield(evidence, "candidate_binding_preserved_by_current_audit") && ...
    logical(evidence.candidate_binding_preserved_by_current_audit), ...
    "SimuVerity:F90:XMED07:CandidateBinding", ...
    "The GROUP_SCORING audit must preserve the sealed candidate binding.");
end

function evidence = localReferenceRepresentation(evidence)
% The source reference extractor already runs the immutable model audit and
% seven scenarios. GROUP_SCORING needs a port-graph representation of those fixed facts;
% this bridge is reachable only after the exact reference file binding/subject guard.
assert(isfield(evidence, "schema") && evidence.schema == ...
    "simuverity.f90-xmed07-evidence.v1" && ...
    isfield(evidence, "static_audit") && isstruct(evidence.static_audit), ...
    "SimuVerity:F90:XMED07:ReferenceEvidence", ...
    "The reference representation bridge requires source METRICS evidence.");
static = evidence.static_audit;
causal = struct( ...
    "command_to_supervisor", localStaticFlag(static, "top_command_to_software"), ...
    "supervisor_to_motor_controller", localStaticFlag(static, "software_reference_to_motor_controller"), ...
    "motor_controller_to_actuator", localStaticFlag(static, "top_software_to_motor_plant"), ...
    "speed_to_motor_controller", localStaticFlag(static, "measured_speed_to_motor_controller"), ...
    "speed_to_occlusion_detector", localStaticFlag(static, "measured_speed_to_occlusion_detector"), ...
    "force_to_occlusion_detector", localStaticFlag(static, "load_force_to_occlusion_detector"), ...
    "occlusion_detector_to_supervisor", localStaticFlag(static, "occlusion_to_supervisory"), ...
    "remaining_to_supervisor", localStaticFlag(static, "remaining_units_to_supervisory"), ...
    "controller_components", localStaticFlag(static, "controller_component_models_present"));
physical = struct( ...
    "main_chain", localStaticFlag(static, "physical_motor_present") && ...
        localStaticFlag(static, "physical_transmission_present") && ...
        localStaticFlag(static, "physical_slide_present") && ...
        localStaticFlag(static, "physical_reservoir_present") && ...
        localStaticFlag(static, "physical_delivery_line_present") && ...
        localStaticFlag(static, "physical_patient_boundary_present"), ...
    "upstream_flow_sensor", localStaticFlag(static, "physical_upstream_flow_sensor_present"), ...
    "patient_flow_sensor", localStaticFlag(static, "physical_patient_flow_sensor_present"), ...
    "occlusion_source", localStaticFlag(static, "native_occlusion_source_present"));
static.structure_port_graph = localReferenceGraph(causal, physical);
static.structure_representation = "exact-reference-static-audit-to-port-graph";
static.structure_representation_subject = "reference";
static.structure_representation_model_file_presence = ...
    "present";
evidence.static_audit = static;
evidence.schema = "simuverity.f90-xmed07-evidence.v1";
evidence.static_audit_method = ...
    "simuverity.f90-xmed07-exact-reference-port-representation.v1";
evidence.candidate_evidence_ready = true;
evidence.evidence_contract_valid = false;
evidence.extraction_only = true;
evidence.score_fields_present = false;
end

function graph = localReferenceGraph(causal, physical)
names = ["motion_state"; "delivery_state"; "safety_state"];
nodes = struct("id", {}, "block_type", {}, "input_ports", {}, "output_ports", {});
% jsonencode flattens an Nx2 cell matrix.  Keep each directed edge in its
% own cell so the current graph consumes an array of [source, target] pairs.
edges = cell(0, 1);
candidates = struct;
sources = struct;
collisions = struct;
for nameIndex = 1:numel(names)
    name = names(nameIndex);
    groups = cell(4, 1);
    for roleIndex = 1:4
        sourceId = "reference/" + name + "/source_" + roleIndex;
        sourcePort = sourceId + "/out";
        nodes(end + 1) = struct("id", sourceId, ...
            "block_type", "reference_static_audit_role", "input_ports", {{}}, ...
            "output_ports", {{char(sourcePort)}}); %#ok<AGROW>
        groups{roleIndex} = {char(sourcePort)};
    end
    sinkId = "reference/" + name + "/ToWorkspace";
    sinkPort = sinkId + "/in";
    nodes(end + 1) = struct("id", sinkId, "block_type", "ToWorkspace", ...
        "input_ports", {{char(sinkPort)}}, "output_ports", {{}}); %#ok<AGROW>
    for roleIndex = 1:4
        edges{end + 1, 1} = {groups{roleIndex}{1}, char(sinkPort)}; %#ok<AGROW>
    end
    candidates.(char(name)) = {struct( ...
        "container_kind", "simulation_output_toworkspace", ...
        "container_node_id", sinkId, "anchor_port_id", sinkPort)};
    sources.(char(name)) = groups;
    collisions.(char(name)) = 0;
end
graph = struct( ...
    "schema", "simuverity.f90-xmed07-port-graph.v1", ...
    "nodes", nodes, "edges", {edges}, ...
    "public_output_candidates", candidates, ...
    "public_output_source_ports", sources, ...
    "unsupported_direct_name_collisions", collisions, ...
    "current_causal_facts", causal, "current_physical_facts", physical, ...
    "port_identity_complete", true, ...
    "bus_creator_selector_all_to_all", false, ...
    "candidate_display_names_emitted", false, ...
    "candidate_mask_types_emitted", false, ...
    "nested_or_top_level_outport_grants_public_binding", false, ...
    "candidate_logging_aliases_union_with_direct_outputs", false);
end

function value = localStaticFlag(static, name)
value = isfield(static, name) && logical(static.(name));
end

function localWriteJson(pathValue, value)
fid = fopen(pathValue, "w", "n", "UTF-8");
assert(fid >= 0, "SimuVerity:F90:XMED07:Write", "Cannot write reference evidence.");
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fprintf(fid, "%s\n", jsonencode(value, PrettyPrint=true));
end

function localRequireBinding(pathValue, expected)
assert(isfile(pathValue) && localFilePresence(pathValue) == lower(string(expected)), ...
    "SimuVerity:F90:XMED07:DependencyBinding", ...
    "A declared GROUP_SCORING evaluator dependency is missing or changed.");
end

function value = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
value = "present";
end
